19: function rr(g, x, y, w, h, r) {
20:   r = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
21:   g.beginPath();
22:   g.moveTo(x + r, y);
23:   g.arcTo(x + w, y, x + w, y + h, r);
24:   g.arcTo(x + w, y + h, x, y + h, r);
25:   g.arcTo(x, y + h, x, y, r);
26:   g.arcTo(x, y, x + w, y, r);
27:   g.closePath();
