32:     const r = i % 2 === 0 ? r1 : r2;
33:     const a = rot + i * Math.PI / points;
34:     const x = Math.cos(a) * r, y = Math.sin(a) * r;
35:     i ? g.lineTo(x, y) : g.moveTo(x, y);
36:   }
37:   g.closePath();
38: }
