175: let AC = null, masterGain = null, noiseBuffer = null;
176: function ensureAudio() {
177:   if (AC) { if (AC.state === 'suspended') AC.resume(); return; }
178:   const C = window.AudioContext || window.webkitAudioContext;
179:   if (!C) return;
180:   AC = new C();
181:   masterGain = AC.createGain();
182:   masterGain.gain.value = profile.muted ? 0 : 0.34;
183:   masterGain.connect(AC.destination);
184:   const len = Math.floor(AC.sampleRate * 1.2);
185:   noiseBuffer = AC.createBuffer(1, len, AC.sampleRate);
186:   const d = noiseBuffer.getChannelData(0);
187:   for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
188: }
189: function setMuted(m, silent) {
190:   profile.muted = !!m;
191:   if (masterGain) masterGain.gain.value = m ? 0 : 0.34;
192:   el.btnMute.classList.toggle('muted', !!m);
193:   el.btnMute.setAttribute('aria-pressed', m ? 'true' : 'false');
194:   el.btnMute.setAttribute('aria-label', m ? 'Unmute sound' : 'Mute sound');
195:   el.btnMute.title = m ? 'Unmute sound' : 'Mute sound';
