198: function blip(freq, dur, type = 'sine', vol = 0.18, slide = 0, delay = 0) {
199:   if (!AC || profile.muted) return;
200:   const t0 = AC.currentTime + delay;
201:   const o = AC.createOscillator(), gn = AC.createGain();
202:   o.type = type;
203:   o.frequency.setValueAtTime(freq, t0);
204:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(35, freq + slide), t0 + dur);
205:   gn.gain.setValueAtTime(0.0001, t0);
206:   gn.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
207:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
208:   o.connect(gn); gn.connect(masterGain);
209:   o.start(t0); o.stop(t0 + dur + 0.03);
210: }
211: function noiseBurst(dur, vol = 0.18, freq = 1100, delay = 0, type = 'bandpass', slideTo) {
212:   if (!AC || profile.muted || !noiseBuffer) return;
213:   const t0 = AC.currentTime + delay;
214:   const src = AC.createBufferSource();
215:   src.buffer = noiseBuffer;
216:   const f = AC.createBiquadFilter();
217:   f.type = type; f.frequency.setValueAtTime(freq, t0);
218:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
219:   const gn = AC.createGain();
220:   gn.gain.setValueAtTime(vol, t0);
221:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
222:   src.connect(f); f.connect(gn); gn.connect(masterGain);
223:   src.start(t0); src.stop(t0 + dur + 0.02);
224: }
