304: function computeLayout() {
305:   const prevW = W, prevH = H, prevFloor = floorY;
306:   W = window.innerWidth;
307:   H = window.innerHeight;
308:   DPR = Math.min(window.devicePixelRatio || 1, 2);
309:   el.canvas.width = Math.round(W * DPR);
310:   el.canvas.height = Math.round(H * DPR);
311:   el.canvas.style.width = W + 'px';
312:   el.canvas.style.height = H + 'px';
