314:   isTouch = window.matchMedia('(pointer: coarse)').matches || (navigator.maxTouchPoints || 0) > 0;
315:   document.body.classList.toggle('touch', isTouch);
316:   S = clamp(Math.sqrt(W * H) / 860, 0.66, 1.3);
317:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
318:   arenaTop = isTouch ? 78 : 96;
319:   floorY = H - apron;
320:   const margin = isTouch ? 14 : 24;
321:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
322: 
323:   skyGrad = ctx.createLinearGradient(0, 0, 0, Math.max(200, floorY));
324:   skyGrad.addColorStop(0, '#3a1e66');
325:   skyGrad.addColorStop(0.38, '#8a3a8d');
326:   skyGrad.addColorStop(0.64, '#f56d73');
327:   skyGrad.addColorStop(0.85, '#ffb35e');
328:   skyGrad.addColorStop(1, '#ffe29a');
329:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
330:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
331:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
332:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
333: 
334:   rebuildDecor();
335:   if (prevW && (prevW !== W || prevH !== H)) {
336:     const sx = W / prevW;
337:     const sy = H / prevFloor;
338:     for (const p of players) {
339:       p.x *= sx;
340:       p.y = prevFloor ? p.y * sy : floorY;
341:       p.y = Math.min(p.y, floorY);
342:     }
343:     for (const b of balls) { b.x *= sx; b.y *= sy; }
344:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
345:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
346:   }
347: }
