349: function generatePlatforms() {
350:   const bw = arena.right - arena.left;
351:   // Three times as many, three times smaller ledges: a denser field of
352:   // small moving platforms instead of a few big ones.
353:   const step = 110 * S;
354:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
355:   let levels = 1;
356:   if (maxRise >= step * 2) levels = 2;
357:   if (maxRise >= step * 3) levels = 3;
358:   if (maxRise >= step * 4) levels = 4;
359: 
360:   const cols = 3;
361:   const pw = clamp(75 * S, bw * 0.08, bw * 0.13);
362: 
363:   platforms = [];
364:   for (let i = 0; i < levels; i++) {
365:     for (let k = 0; k < cols; k++) {
366:       const x = arena.left + (k + 0.5) * (bw / cols) - pw / 2 + rand(-bw * 0.04, bw * 0.04);
367:       platforms.push({
368:         x: clamp(x, arena.left + 8, arena.right - pw - 8),
369:         y: floorY - step * (i + 1),
370:         w: pw,
371:         h: 14 * S,
372:         style: (i + k) % 3,
373:         vx: ((i + k) % 2 === 0 ? 1 : -1) * rand(40, 110) * S,
374:       });
375:     }
376:   }
377: 
378:   for (const p of platforms) {
379:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
380:     p.y = Math.max(p.y, arena.top + 54 * S);
381:   }
382: }
