364: /* ------------------------------ input ------------------------------ */
365: const keys = new Set();
366: const touchAxes = [0, 0];          // analog joystick output, -1..1
367: const joysticks = [];
368: const pointerOwners = new Map();
369: const PLAYER_KEYS = [
370:   { left: ['KeyA'], right: ['KeyD'], jump: ['KeyW'], throw: ['Space'] },
371:   { left: ['ArrowLeft'], right: ['ArrowRight'], jump: ['ArrowUp'], throw: ['Enter', 'Numpad0'] },
372: ];
373: function hasAny(code, list) { return list.includes(code); }
374: function playerForKey(code) {
375:   for (let i = 0; i < 2; i++) {
376:     const m = PLAYER_KEYS[i];
377:     if (hasAny(code, m.left) || hasAny(code, m.right) || hasAny(code, m.jump) || hasAny(code, m.throw)) return { i, action: hasAny(code, m.left) ? 'left' : hasAny(code, m.right) ? 'right' : hasAny(code, m.jump) ? 'jump' : 'throw' };
378:   }
379:   return null;
380: }
381: function isModalOpen() {
382:   return !el.screenArcade.classList.contains('hidden') || !el.screenHow.classList.contains('hidden');
383: }
384: function getInputDir(p) {
385:   if (p.ai) return p.aiMove;
386:   let dir = 0;
387:   if (p.idx === 0) {
388:     if (keys.has('KeyA')) dir--;
389:     if (keys.has('KeyD')) dir++;
390:   } else {
391:     if (keys.has('ArrowLeft')) dir--;
392:     if (keys.has('ArrowRight')) dir++;
393:   }
394:   const axis = touchAxes[p.idx];
395:   if (axis) dir += axis;
396:   return clamp(dir, -1, 1);
397: }
398: function doJump(p, strength = 1) {
399:   if (!p || p.ko) return;
400:   p.vy = -jumpSpeedFor() * strength;
401:   p.onGround = false;
402:   p.coyote = 0;
403:   p.jumpBuffer = 0;
404:   if (p.wasGround) { dust(p.x, p.y, 4); sfx.jump(); }
405:   else {
406:     dust(p.x, p.y - 15 * S, 4);
407:     burst(p.x, p.y - 20 * S, P_COLORS[p.idx], 6, 0.5, 'dot');
408:     sfx.jump();
409:   }
410: }
411: function queueJump(p) {
412:   if (!p || p.ko) return;
413:   if (state !== 'play' && state !== 'title') return;
414:   p.jumpBuffer = 0.13;
415: }
416: function requestThrow(p) {
417:   if (!p || p.ko) return;
418:   if (state !== 'play' && state !== 'title') return;
419:   beginThrow(p);
420: }
421: function releaseThrowInput(p) {
422:   if (!p) return;
423:   if (p.charging) releaseThrow(p);
424: }
