426: function onKeyDown(e) {
427:   ensureAudio();
428:   if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Enter'].includes(e.code)) e.preventDefault();
429:   if (e.repeat) return;
430:   keys.add(e.code);
431: 
432:   if (isModalOpen()) {
433:     if (e.code === 'Escape') {
434:       if (!el.screenHow.classList.contains('hidden')) closeHow();
435:       else closeArcade();
436:     }
437:     return;
438:   }
439:   if (state === 'title') {
440:     if (e.code === 'Enter' || e.code === 'Space') { sfx.ui(); newMatch('2p', titleChars); }
441:     return;
442:   }
443:   if (state === 'matchEnd') {
444:     if (endShown && (e.code === 'Enter' || e.code === 'Space')) rematch();
445:     return;
446:   }
447:   if (e.code === 'Escape') {
448:     if (paused) pauseGame(false);
449:     else pauseGame(true);
450:     return;
451:   }
452:   if (e.code === 'KeyM') { setMuted(!profile.muted); return; }
453:   if (paused) return;
454: 
455:   const pk = playerForKey(e.code);
456:   if (!pk) return;
457:   const p = players[pk.i];
458:   if (!p) return;
459:   if (pk.action === 'jump') queueJump(p);
460:   else if (pk.action === 'throw' && state === 'play') requestThrow(p);
461: }
462: 
463: function onKeyUp(e) {
464:   keys.delete(e.code);
465:   const pk = playerForKey(e.code);
466:   if (!pk) return;
467:   const p = players[pk.i];
468:   if (!p) return;
469:   if (pk.action === 'throw') releaseThrowInput(p);
470:   if (pk.action === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
471: }
