473: function bindTouch() {
474:   document.querySelectorAll('.tbtn[data-act]').forEach(btn => {
475:     const pad = btn.closest('.pad');
476:     const pIdx = Number(pad.dataset.player);
477:     const act = btn.dataset.act;
478:     const down = e => {
479:       e.preventDefault();
480:       ensureAudio();
481:       if (state !== 'play' && state !== 'title') return;
482:       if (paused) return;
483:       btn.classList.add('pressed');
484:       pointerOwners.set(e.pointerId, { pIdx, act, btn });
485:       try { btn.setPointerCapture?.(e.pointerId); } catch {}
486:       const p = players[pIdx];
487:       if (!p) return;
488:       if (act === 'jump') queueJump(p);
489:       if (act === 'throw') {
490:         const moving = Math.abs(getInputDir(p)) > 0.15;
491:         requestThrow(p);
492:         if (!moving) setTimeout(() => releaseThrowInput(p), 90);
493:       }
494:     };
495:     const up = e => {
496:       const own = pointerOwners.get(e.pointerId);
497:       if (!own || own.pIdx !== pIdx) return;
498:       pointerOwners.delete(e.pointerId);
499:       btn.classList.remove('pressed');
500:       const p = players[pIdx];
501:       if (!p) return;
502:       if (act === 'throw') releaseThrowInput(p);
503:       if (act === 'jump' && p.vy < -60 * S) p.vy *= 0.8;
504:     };
505:     btn.addEventListener('pointerdown', down);
506:     btn.addEventListener('pointerup', up);
507:     btn.addEventListener('pointercancel', up);
508:     btn.addEventListener('lostpointercapture', up);
509:     btn.addEventListener('contextmenu', e => e.preventDefault());
510:   });
511: }
