513: /* ------------------------------ virtual joysticks ------------------------------ */
514: function bindJoysticks() {
515:   joysticks.length = 0;
516:   document.querySelectorAll('#touch .joystick').forEach(joyEl => {
517:     const pad = joyEl.closest('.pad');
518:     const pIdx = Number(pad.dataset.player);
519:     const base = joyEl.querySelector('.stick-base');
520:     const knob = joyEl.querySelector('.stick-knob');
521:     const j = { el: joyEl, knob, pIdx, pointerId: null, max: 1, jumpLatch: false };
522:     joysticks.push(j);
523: 
524:     const centerOf = () => {
525:       const r = base.getBoundingClientRect();
526:       j.max = Math.max(1, r.width * 0.3);
527:       return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
528:     };
529:     const setAxis = (dx, dy) => {
530:       const raw = Math.hypot(dx, dy);
531:       const scale = raw > j.max ? j.max / raw : 1;
532:       const kx = dx * scale, ky = dy * scale;
533:       knob.style.transform = `translate(-50%, -50%) translate(${kx}px, ${ky}px)`;
534:       const x = clamp(kx / j.max, -1, 1);
535:       const dead = 0.16;
536:       touchAxes[pIdx] = Math.sign(x) * clamp((Math.abs(x) - dead) / (1 - dead), 0, 1);
537:       // drop through platforms on downward flick
538:       if (ky > j.max * 0.5) {
539:         const pp = players[pIdx];
540:         if (pp) {
541:           pp.dropThrough = 0.25;
542:           if (pp.onGround && pp.y < floorY - 1) { pp.vy = 120 * S; pp.onGround = false; }
543:         }
544:       }
545:       // jump on upward flick
546:       if (ky < -j.max * 0.5 && !j.jumpLatch) {
547:         j.jumpLatch = true;
548:         const p = players[pIdx];
549:         if (p) queueJump(p);
550:       }
551:       if (ky > -j.max * 0.25) j.jumpLatch = false;
552:     };
553:     const release = e => {
554:       if (j.pointerId === null) return;
555:       if (e && e.pointerId !== undefined && e.pointerId !== j.pointerId) return;
556:       const p = players[pIdx];
557:       if (p && p.charging) {
558:         releaseThrow(p);
559:         p.needsMove = true;
560:       }
561:       // restore default position
562:       joyEl.style.position = '';
563:       joyEl.style.left = '';
564:       joyEl.style.top = '';
565:       joyEl.style.right = '';
566:       joyEl.style.bottom = '';
567:       j.pointerId = null;
568:       j.jumpLatch = false;
569:       touchAxes[pIdx] = 0;
570:       joyEl.classList.remove('active');
571:       knob.style.transform = 'translate(-50%, -50%)';
572:     };
573:     j.centerOf = centerOf;
574:     j.setAxis = setAxis;
575:     j.releaseFn = release;
576:     const canUse = () => (state === 'play' || state === 'title') && !paused;
577: 
578:     joyEl.addEventListener('pointermove', e => {
579:       if (j.pointerId !== e.pointerId) return;
580:       e.preventDefault();
581:       const c = centerOf();
582:       setAxis(e.clientX - c.x, e.clientY - c.y);
583:     });
584:     joyEl.addEventListener('pointerup', release);
585:     joyEl.addEventListener('pointercancel', release);
586:     joyEl.addEventListener('lostpointercapture', release);
587:     joyEl.addEventListener('contextmenu', e => e.preventDefault());
588:   });
589: }
590: 
591:   // Global multi-touch routing keeps both joysticks responsive even if
592:   // pointer capture is lost or a finger drifts outside its pad.
593:   if (!window.__bonkJoyBound) {
594:     window.__bonkJoyBound = true;
595:     window.addEventListener('pointermove', e => {
596:       const j = joysticks.find(x => x.pointerId === e.pointerId);
597:       if (!j) return;
598:       e.preventDefault();
599:       const c = j.centerOf();
600:       j.setAxis(e.clientX - c.x, e.clientY - c.y);
601:     }, { passive: false });
602:     const end = e => {
603:       const j = joysticks.find(x => x.pointerId === e.pointerId);
604:       if (!j) return;
605:       j.releaseFn(e);
606:     };
607:     window.addEventListener('pointerup', end);
608:     window.addEventListener('pointercancel', end);
609:     window.addEventListener('lostpointercapture', end);
610:   }
611: 
612:   // Full-half touch zones: touching anywhere in a player's half activates
613:   // and floats that player's joystick at the touch point.
614:   if (!window.__bonkJoyZones) {
615:     window.__bonkJoyZones = true;
616:     window.addEventListener('pointerdown', e => {
617:       if (!((state === 'play' || state === 'title') && !paused)) return;
618:       const target = e.target;
619:       if (target && target.closest && target.closest('button, .btn, .tab, input, a, .panel')) return;
620:       const idx = e.clientX < window.innerWidth / 2 ? 0 : 1;
621:       const j = joysticks[idx];
622:       if (!j || j.pointerId !== null) return;
623:       ensureAudio();
624:       const joyEl = j.el;
625:       const pad = joyEl.closest('.pad');
626:       const padRect = pad.getBoundingClientRect();
627:       const halfW = joyEl.offsetWidth / 2;
628:       const halfH = joyEl.offsetHeight / 2;
629:       const mid = window.innerWidth / 2;
630:       let cx = e.clientX, cy = e.clientY;
631:       if (idx === 0) cx = Math.max(halfW, Math.min(cx, mid - halfW));
632:       else cx = Math.max(mid + halfW, Math.min(cx, window.innerWidth - halfW));
633:       cy = Math.max(halfH, Math.min(cy, window.innerHeight - halfH));
634:       joyEl.style.position = 'absolute';
635:       joyEl.style.left = (cx - padRect.left - halfW) + 'px';
636:       joyEl.style.top = (cy - padRect.top - halfH) + 'px';
637:       joyEl.style.right = 'auto';
638:       joyEl.style.bottom = 'auto';
639:       j.pointerId = e.pointerId;
640:       joyEl.classList.add('active');
641:       try { joyEl.setPointerCapture(e.pointerId); } catch {}
642:       const c = j.centerOf();
643:       j.setAxis(e.clientX - c.x, e.clientY - c.y);
644:       e.preventDefault();
645:     }, { passive: false });
646:   }
647:   // expose canUse for zone handler
648: 
649: function resetJoysticks() {
650:   touchAxes[0] = 0;
651:   touchAxes[1] = 0;
652:   for (const j of joysticks) {
653:     j.pointerId = null;
654:     j.jumpLatch = false;
655:     j.knob.style.transform = 'translate(-50%, -50%)';
656:   }
657:   pointerOwners.clear();
658:   document.querySelectorAll('.tbtn.pressed').forEach(b => b.classList.remove('pressed'));
659: }
