661: /* ------------------------------ player update ------------------------------ */
662: function updatePlayer(p, dt) {
663:   if (!p) return;
664:   // timers
665:   p.throwCd = Math.max(0, p.throwCd - dt);
666:   p.throwAnim = Math.max(0, p.throwAnim - dt);
667:   p.rageT = Math.max(0, (p.rageT || 0) - dt);
668:   p.shieldT = Math.max(0, (p.shieldT || 0) - dt);
669:   p.catchAnim = Math.max(0, p.catchAnim - dt);
670:   p.invuln = Math.max(0, p.invuln - dt);
671:   p.hitstun = Math.max(0, p.hitstun - dt);
672:   p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
673:   p.dropThrough = Math.max(0, (p.dropThrough || 0) - dt);
674:   p.blinkTimer -= dt;
675:   if (p.blinkTimer <= 0) { p.blink = 0.11; p.blinkTimer = rand(2.2, 4.8); }
676:   p.blink = Math.max(0, p.blink - dt);
677:   if (p.ko) {
678:     p.koT += dt;
679:     p.vy += gravityFor() * dt;
680:     p.x += p.vx * dt;
681:     p.y += p.vy * dt;
682:     p.vx *= Math.pow(0.2, dt);
683:     if (p.y > floorY) { p.y = floorY; p.vy = 0; p.vx *= 0.7; }
684:     p.x = clamp(p.x, arena.left + 22 * S, arena.right - 22 * S);
685:     p.onGround = p.y >= floorY - 0.5;
686:     return;
687:   }
688: 
689:   if (p.ai && (state === 'play' || state === 'title')) updateAI(p, dt);
690: 
691:   const canControl = state === 'play' && !paused;
692:   let dir = canControl ? getInputDir(p) : 0;
693:   if (p.hitstun > 0) dir = 0;
694: 
695:   // drop through platforms on down input
696:   if (state === 'play' && canControl && !p.ai) {
697:     const downHeld = (p.idx === 0 && keys.has('KeyS')) || (p.idx === 1 && keys.has('ArrowDown'));
698:     if (downHeld) {
699:       p.dropThrough = 0.2;
700:       if (p.onGround && p.y < floorY - 1) { p.vy = 120 * S; p.onGround = false; }
701:     }
702:   }
703: 
704:   // auto-charge / auto-fire for human players
705:   if (state === 'play' && canControl && !p.ai && !p.ko && p.hitstun <= 0) {
706:     const moving = Math.abs(dir) > 0.15;
707:     if (moving) {
708:       if (p.needsMove) p.needsMove = false;
709:       if (!p.charging && p.throwCd <= 0 && !p.needsMove) beginThrow(p);
710:     }
711:   }
712: 
713:   // jump buffering
714:   if (p.jumpBuffer > 0 && canControl) {
715:     if (p.onGround || p.coyote > 0) { p.wasGround = true; doJump(p, 1); p.jumpsLeft = 1; }
716:     else if (p.jumpsLeft > 0) { p.jumpsLeft--; p.wasGround = false; doJump(p, 0.88); }
717:   }
718: 
719:   const maxSp = runSpeedFor() * (p.charging ? 0.58 : 1) * (p.hitstun > 0 ? 0.5 : 1);
720:   if (dir !== 0) {
721:     p.facing = Math.sign(dir) || p.facing;
722:     p.vx += dir * 5800 * S * dt;
723:     p.vx = clamp(p.vx, -maxSp, maxSp);
724:   } else {
725:     p.vx *= Math.pow(0.0009, dt);
726:     if (Math.abs(p.vx) < 4 * S) p.vx = 0;
727:   }
728: 
729:   if (p.charging && canControl) {
730:     p.charge = Math.min(1, p.charge + dt / 1.24);
731:     p.chargeFx = (p.chargeFx || 0) - dt;
732:     if (p.chargeFx <= 0) {
733:       p.chargeFx = 0.07;
734:       const h = handPoint(p);
735:       addParticle({
736:         x: h.x + rand(-14, 14) * S, y: h.y + rand(-14, 14) * S,
737:         vx: rand(-30, 30) * S, vy: rand(-70, -10) * S,
738:         life: rand(0.2, 0.45), size: rand(2, 4.5) * S,
739:         color: P_COLORS[p.idx], kind: 'dot', grav: -60 * S, drag: 0.92,
740:       });
741:     }
742:   } else {
743:     p.charge = 0;
744:   }
745: 
746:   // physics
747:   p.wasGround = p.onGround;
748:   const prevY = p.y;
749:   p.vy += gravityFor() * dt;
750:   p.vy = Math.min(p.vy, 1900 * S);
751:   p.x += p.vx * dt;
752:   p.y += p.vy * dt;
753:   p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
754: 
755:   p.onGround = false;
756:   p.platform = null;
757:   if (p.vy >= 0 && (p.dropThrough || 0) <= 0) {
758:     for (const pl of platforms) {
759:       if (prevY <= pl.y + 2 && p.y >= pl.y && p.y <= pl.y + pl.h + 30 * S &&
760:           p.x + 14 * S > pl.x + 3 && p.x - 14 * S < pl.x + pl.w - 3) {
761:         p.y = pl.y;
762:         p.vy = 0;
763:         p.onGround = true;
764:         p.jumpsLeft = 1;
765:         p.platform = pl;
766:         break;
767:       }
768:     }
769:   }
770:   if (p.y >= floorY) {
771:     p.y = floorY;
772:     p.vy = 0;
773:     p.onGround = true;
774:     p.jumpsLeft = 1;
775:     p.platform = null;
776:   }
777:   if (p.onGround) p.coyote = 0.1;
778:   else p.coyote = Math.max(0, p.coyote - dt);
779: 
780:   // carry on moving platforms
781:   if (p.onGround && p.platform) {
782:     p.x += (p.platform.vx || 0) * dt;
783:     p.x = clamp(p.x, arena.left + 18 * S, arena.right - 18 * S);
784:   }
785: 
786:   if (p.onGround && !p.wasGround && p.vy === 0) {
787:     dust(p.x, p.y, 5);
788:     if (Math.abs(p.vx) > 40 * S || state === 'play') sfx.land();
789:   }
790: 
791:   p.runPhase += Math.abs(p.vx) * dt * 0.033;
792: }
