794: function updateAI(p, dt) {
795:   const opp = getOpponent(p);
796:   if (!opp) return;
797:   p.aiTimer -= dt;
798:   p.aiStrafeTimer -= dt;
799:   p.aiJumpCd -= dt;
800: 
801:   if (state === 'title') {
802:     p.demoT += dt;
803:     p.demoThrow -= dt;
804:     const home = arena.left + (arena.right - arena.left) * (p.idx === 0 ? 0.13 : 0.87);
805:     const tx = home + Math.sin(p.demoT * 0.55 + p.idx * 2.1) * 70 * S;
806:     p.aiMove = clamp((tx - p.x) / (70 * S), -1, 1);
807:     if (p.charging) {
808:       p.aiCharge += dt;
809:       if (p.aiCharge > p.aiHold) releaseThrow(p);
810:     } else if (p.demoThrow <= 0 && p.throwCd <= 0 && balls.length < 3) {
811:       beginThrow(p);
812:       p.aiHold = rand(0.35, 0.85);
813:       p.aiCharge = 0;
814:       p.demoThrow = rand(2.4, 4.4);
815:     }
816:     if (p.onGround && Math.random() < dt * 0.18) p.jumpBuffer = 0.1;
817:     return;
818:   }
819: 
820:   if (p.aiStrafeTimer <= 0) {
821:     p.aiStrafe = pick([-1, 0, 1]);
822:     p.aiStrafeTimer = rand(0.7, 1.7);
823:   }
824:   const dx = opp.x - p.x;
825:   const adx = Math.abs(dx);
826:   let move = 0;
827:   if (adx > 460 * S) move = Math.sign(dx);
828:   else if (adx < 200 * S) move = -Math.sign(dx);
829:   else move = p.aiStrafe * 0.65;
830:   if (p.x < arena.left + 70 * S) move = 1;
831:   if (p.x > arena.right - 70 * S) move = -1;
832:   p.aiMove = clamp(move, -1, 1);
833: 
834:   const threat = balls.find(b => !b.dead && b.owner !== p.idx &&
835:     dist(b.x, b.y, p.x, p.y - 42 * S) < 235 * S &&
836:     (b.vx * (p.x - b.x) + b.vy * (p.y - 42 * S - b.y)) > 0);
